let writeQueue = Promise.resolve();
let liveDbCache = null;
let liveDbReadInFlight = null;

async function ensureDataDir() {
  await fs.mkdir(DATA_DIR, { recursive: true });
}

// v190h: bounded-memory JSON persistence.
// The old writers called JSON.stringify() on an entire database, temporarily
// creating another full database-sized string in memory. This writer walks the
// value and flushes small chunks to an atomic temporary file instead.
const NEXTGEN_JSON_WRITE_BUFFER_BYTES = Math.max(
  64 * 1024,
  Math.min(4 * 1024 * 1024, Number(process.env.NEXTGEN_JSON_WRITE_BUFFER_BYTES || 512 * 1024) || 512 * 1024)
);

async function ngWriteJsonAtomicStreaming(filePath, value, label = "database", { gzip = false } = {}) {
  const tempPath = `${filePath}.tmp`;
  let handle = null;
  let streamInput = null;
  let streamPipeline = null;
  let pending = "";
  let pendingBytes = 0;
  const activeObjects = new WeakSet();

  const flush = async () => {
    if (!pending) return;
    const chunk = pending;
    pending = "";
    pendingBytes = 0;
    if (streamInput) {
      if (!streamInput.write(chunk, "utf8")) await new Promise((resolve) => streamInput.once("drain", resolve));
    } else {
      await handle.write(chunk, null, "utf8");
    }
  };

  const writePiece = async (piece) => {
    const text = String(piece ?? "");
    if (!text) return;
    const textBytes = Buffer.byteLength(text, "utf8");
    if (textBytes >= NEXTGEN_JSON_WRITE_BUFFER_BYTES) {
      await flush();
      if (streamInput) {
        if (!streamInput.write(text, "utf8")) await new Promise((resolve) => streamInput.once("drain", resolve));
      } else {
        await handle.write(text, null, "utf8");
      }
      return;
    }
    pending += text;
    pendingBytes += textBytes;
    if (pendingBytes >= NEXTGEN_JSON_WRITE_BUFFER_BYTES) {
      await flush();
    }
  };

  const writeJsonString = async (input) => {
    const text = String(input);
    await writePiece('"');
    const charsPerChunk = 64 * 1024;
    for (let start = 0; start < text.length;) {
      let end = Math.min(text.length, start + charsPerChunk);
      if (end < text.length) {
        const finalCode = text.charCodeAt(end - 1);
        if (finalCode >= 0xd800 && finalCode <= 0xdbff) end -= 1;
      }
      const escaped = JSON.stringify(text.slice(start, end)).slice(1, -1);
      await writePiece(escaped);
      start = end;
    }
    await writePiece('"');
  };

  const writeValue = async (item, inArray = false) => {
    if (item === null) {
      await writePiece("null");
      return;
    }

    const type = typeof item;
    if (type === "string") {
      await writeJsonString(item);
      return;
    }
    if (type === "number") {
      await writePiece(Number.isFinite(item) ? String(item) : "null");
      return;
    }
    if (type === "boolean") {
      await writePiece(item ? "true" : "false");
      return;
    }
    if (type === "bigint") {
      throw new TypeError("Cannot serialize BigInt to JSON");
    }
    if (type === "undefined" || type === "function" || type === "symbol") {
      await writePiece(inArray ? "null" : "null");
      return;
    }

    if (typeof item?.toJSON === "function") {
      await writeValue(item.toJSON(), inArray);
      return;
    }
    if (activeObjects.has(item)) {
      throw new TypeError(`Cannot serialize circular structure in ${label}`);
    }
    activeObjects.add(item);

    try {
      if (Array.isArray(item)) {
        await writePiece("[");
        for (let index = 0; index < item.length; index += 1) {
          if (index) await writePiece(",");
          await writeValue(item[index], true);
        }
        await writePiece("]");
        return;
      }

      await writePiece("{");
      let written = 0;
      for (const [key, child] of Object.entries(item)) {
        const childType = typeof child;
        if (childType === "undefined" || childType === "function" || childType === "symbol") continue;
        if (written) await writePiece(",");
        await writeJsonString(key);
        await writePiece(":");
        await writeValue(child, false);
        written += 1;
      }
      await writePiece("}");
    } finally {
      activeObjects.delete(item);
    }
  };

  try {
    await ensureDataDir();
    if (gzip) {
      streamInput = new PassThrough();
      streamPipeline = pipelineStreams(
        streamInput,
        createGzip({ level: 9 }),
        fsSync.createWriteStream(tempPath, { flags: "w" }),
      );
    } else {
      handle = await fs.open(tempPath, "w");
    }
    await writeValue(value, false);
    await flush();
    if (streamInput) {
      streamInput.end();
      await streamPipeline;
      streamInput = null;
      streamPipeline = null;
    } else {
      await handle.sync();
      await handle.close();
      handle = null;
    }
    await fs.rename(tempPath, filePath);
  } catch (error) {
    try { streamInput?.destroy(error); } catch {}
    try { await streamPipeline; } catch {}
    try { if (handle) await handle.close(); } catch {}
    try { await fs.unlink(tempPath); } catch {}
    throw error;
  }
}

const NEXTGEN_RENDER_MEMORY_LIMIT_MB = Math.max(256, Number(process.env.NEXTGEN_RENDER_MEMORY_LIMIT_MB || 2048) || 2048);
const NEXTGEN_BACKGROUND_MEMORY_SOFT_PERCENT = Math.max(50, Math.min(90, Number(process.env.NEXTGEN_BACKGROUND_MEMORY_SOFT_PERCENT || 60) || 60));
const NEXTGEN_BACKGROUND_HEAP_SOFT_PERCENT = Math.max(
  50,
  Math.min(90, Number(process.env.NEXTGEN_BACKGROUND_HEAP_SOFT_PERCENT || 72) || 72),
);
const NEXTGEN_AYLA_VIMEO_HEAP_SOFT_PERCENT = Math.max(
  45,
  Math.min(
    80,
    Number(process.env.NEXTGEN_AYLA_VIMEO_HEAP_SOFT_PERCENT || 62) || 62,
  ),
);
const NEXTGEN_AYLA_VIMEO_HEAP_HARD_PERCENT = Math.max(
  NEXTGEN_AYLA_VIMEO_HEAP_SOFT_PERCENT + 5,
  Math.min(
    92,
    Number(process.env.NEXTGEN_AYLA_VIMEO_HEAP_HARD_PERCENT || 80) || 80,
  ),
);

function ngMemoryStatus() {
  const usage = process.memoryUsage();
  const heapLimitBytes = Math.max(1, Number(getHeapStatistics().heap_size_limit || 0));
  const limitBytes = NEXTGEN_RENDER_MEMORY_LIMIT_MB * 1024 * 1024;
  return {
    rss: usage.rss,
    rss_mb: Number((usage.rss / 1024 / 1024).toFixed(1)),
    heap_used_mb: Number((usage.heapUsed / 1024 / 1024).toFixed(1)),
    heap_limit_mb: Number((heapLimitBytes / 1024 / 1024).toFixed(1)),
    heap_percent: Number((usage.heapUsed / heapLimitBytes * 100).toFixed(1)),
    heap_headroom_mb: Number((Math.max(0, heapLimitBytes - usage.heapUsed) / 1024 / 1024).toFixed(1)),
    external_mb: Number((usage.external / 1024 / 1024).toFixed(1)),
    limit_mb: NEXTGEN_RENDER_MEMORY_LIMIT_MB,
    percent: Number((usage.rss / limitBytes * 100).toFixed(1)),
    background_soft_percent: NEXTGEN_BACKGROUND_MEMORY_SOFT_PERCENT,
    background_heap_soft_percent: NEXTGEN_BACKGROUND_HEAP_SOFT_PERCENT,
    ayla_vimeo_heap_soft_percent: NEXTGEN_AYLA_VIMEO_HEAP_SOFT_PERCENT,
    ayla_vimeo_heap_hard_percent: NEXTGEN_AYLA_VIMEO_HEAP_HARD_PERCENT,
  };
}

function ngBackgroundMemoryIsHigh(jobName = "background_job", {
  heapSoftPercent = NEXTGEN_BACKGROUND_HEAP_SOFT_PERCENT,
} = {}) {
  const status = ngMemoryStatus();
  const rssHigh = status.percent >= NEXTGEN_BACKGROUND_MEMORY_SOFT_PERCENT;
  const heapHigh = status.heap_percent >= heapSoftPercent;
  if (!rssHigh && !heapHigh) return false;
  console.warn(
    `${jobName} skipped because RSS is ${status.rss_mb} MB (${status.percent}% of configured limit) `
    + `and V8 heap is ${status.heap_used_mb} MB (${status.heap_percent}% of heap limit)`,
  );
  return true;
}

function ngThrowIfAylaVimeoHeapUnsafe(phase, {
  responseId = "",
  responseStatus = "",
} = {}) {
  const status = ngMemoryStatus();
  if (status.heap_percent < NEXTGEN_AYLA_VIMEO_HEAP_HARD_PERCENT) return;
  const error = new Error(
    `Vimeo classification paused at ${phase}: V8 heap is ${status.heap_used_mb} MB `
    + `(${status.heap_percent}% of its limit)`,
  );
  error.statusCode = 425;
  error.openAIResponseId = String(responseId || "");
  error.openAIResponseStatus = String(responseStatus || "in_progress");
  error.openAIResponseTerminal = false;
  throw error;
}

function ngMergeEmailTemplates(stored = {}) {
  const output = {};
  for (const [key, base] of Object.entries(DEFAULT_EMAIL_TEMPLATES)) {
    output[key] = {
      ...base,
      ...(stored?.[key] || {}),
      key,
      variables: Array.isArray(stored?.[key]?.variables)
        ? stored[key].variables
        : [...(base.variables || [])],
    };
  }
  for (const [key, value] of Object.entries(stored || {})) {
    if (!output[key] && value && typeof value === "object") output[key] = { ...value, key };
  }
  return output;
}

