app.post("/student/video-library/open", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const courseId = String(req.body.course_id || req.body.courseId || "").trim();
    const roadmapDayId = String(req.body.roadmap_day_id || req.body.roadmapDayId || req.body.day_id || "").trim() || null;

    const result = ngRecordVideoLibraryOpenForStudent(db, {
      user,
      courseId,
      roadmapDayId,
      source: String(req.body.source || "video_library_tab_open"),
      metadata: {
        route: "/student/video-library/open",
        lecture_id: req.body.lecture_id || req.body.lectureId || null,
        lecture_title: req.body.lecture_title || req.body.lectureTitle || null,
      },
    });

    if (!result.allowed) {
      return ngBlockLockedFeature(res, "video_library", result.reason);
    }

    await writeLiveDb(db);
    res.json({ success: true, ...result });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message || "Failed to track video library open" });
  }
});


function ngGetExternalLibraryAccessForCourse(db, user, requestedCourseId = "") {
  const cleanCourseId = String(requestedCourseId || "").trim();

  if (!cleanCourseId) {
    return getExternalLibraryAccess(db, user);
  }

  const demoSettings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  const studentId = String(user?.id || "").trim();

  const enrollments = Object.values(db.enrollments || {}).filter((enrollment) => {
    return (
      studentId &&
      String(enrollment.user_id || "") === studentId &&
      String(enrollment.course_id || "") === cleanCourseId
    );
  });

  for (const enrollment of enrollments.filter((item) => item.is_demo !== true)) {
    const plan = enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null;
    if (!plan) continue;
    if (plan.is_active === false) continue;
    if (!isPaidEnrollmentActive(enrollment, plan, db)) continue;
    if (!planIncludesFeature(plan, "video_library")) continue;

    const course = db.courses?.[cleanCourseId] || null;
    const accessDays = Number(enrollment.access_days || getPlanAccessDays(plan));
    const accessEndsAt = ngPaidAccessExpiresAt(enrollment, plan, db)?.toISOString()
      || addDays(new Date(), accessDays).toISOString();

    return {
      allowed: true,
      enrollment,
      plan,
      course,
      accessDays,
      accessEndsAt,
      source: "paid",
    };
  }

  if (demoSettings.enabled !== false && demoSettings.allow_video_library === true) {
    for (const enrollment of enrollments.filter((item) => item.is_demo === true)) {
      if (!isDemoEnrollmentActive(enrollment, demoSettings)) continue;

      const course = db.courses?.[cleanCourseId] || null;
      if (course?.demo_access_enabled === false) continue;

      const accessDays = Number(enrollment.access_days || demoSettings.duration_days || 7);
      const accessEndsAt = enrollment.demo_expiry
        ? new Date(`${enrollment.demo_expiry}T23:59:59`).toISOString()
        : addDays(new Date(), accessDays).toISOString();

      return {
        allowed: true,
        enrollment,
        plan: null,
        course,
        accessDays,
        accessEndsAt,
        source: "demo",
      };
    }
  }

  return {
    allowed: false,
    enrollment: enrollments[0] || null,
    plan: enrollments[0]?.plan_id ? db.plans?.[String(enrollments[0].plan_id)] || null : null,
    course: db.courses?.[cleanCourseId] || null,
    accessDays: 0,
    accessEndsAt: null,
    source: null,
    reason: enrollments.length
      ? "Student has course enrollment, but it is expired, revoked, or the plan does not include video_library."
      : "Student has no enrollment for this course.",
  };
}

app.post("/admin/external-library/access-link", async (req, res) => {
  try {
    await requireAdminOrInstructor(req);

    const email = normalizeEmail(req.body.email || req.body.student_email || req.body.user_email || "");
    const courseId = String(req.body.course_id || req.body.courseId || "").trim();

    if (!email) {
      return res.status(400).json({ success: false, error: "student email is required" });
    }

    const db = await readLiveDb();
    const rawUser = findUserByEmail(db, email);

    if (!rawUser?.id) {
      return res.status(404).json({ success: false, error: "Student account not found for this email" });
    }

    const user = sanitizeUser(rawUser);
    const access = ngGetExternalLibraryAccessForCourse(db, user, courseId);

    const matchingEnrollments = Object.values(db.enrollments || {})
      .filter((enrollment) => {
        if (String(enrollment.user_id || "") !== String(user.id)) return false;
        if (courseId && String(enrollment.course_id || "") !== String(courseId)) return false;
        return true;
      })
      .map((enrollment) => sanitizeAdminEnrollment(enrollment, db));

    if (!access.allowed) {
      return res.status(403).json({
        success: false,
        locked: true,
        feature: "video_library",
        error: access.reason || "Video Library access is not active for this student.",
        student: user,
        requested_course_id: courseId || null,
        enrollments: matchingEnrollments,
        plan: access.plan ? sanitizePlan(access.plan) : null,
        course: access.course ? sanitizeCourse(access.course) : null,
      });
    }

    const token = signExternalLibraryToken({
      user,
      enrollment: access.enrollment,
      plan: access.plan,
      course: access.course,
      accessEndsAt: access.accessEndsAt,
    });

    const baseExternalUrl = EXTERNAL_LIBRARY_URL.replace(/\/$/, "");
    const redirect_url = `${baseExternalUrl}/sso-login?token=${encodeURIComponent(token)}`;
    const verify_url = `${baseExternalUrl}/external-library/sso/verify?token=${encodeURIComponent(token)}`;

    res.json({
      success: true,
      build: NEXTGEN_BACKEND_BUILD,
      source: "admin_external_library_student_link_v177q",
      student: user,
      requested_course_id: courseId || null,
      redirect_url,
      verify_url,
      expires_in_minutes: EXTERNAL_LIBRARY_TOKEN_MINUTES,
      access_ends_at: access.accessEndsAt,
      access_days: access.accessDays,
      access_source: access.source || null,
      enrollment: access.enrollment ? sanitizeAdminEnrollment(access.enrollment, db) : null,
      plan: access.plan ? sanitizePlan(access.plan) : null,
      course: access.course ? sanitizeCourse(access.course) : null,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to generate admin external library access link",
    });
  }
});

app.post("/student/external-library/access", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);

    if (user.role !== "student" && user.role !== "admin") {
      return res.status(403).json({
        success: false,
        error: "Only students can open the external video library",
      });
    }

    const db = await readLiveDb();
    const access = getExternalLibraryAccess(db, user);

    if (!access.allowed) {
      return res.status(403).json({
        success: false,
        locked: true,
        feature: "video_library",
        upgrade_url: "/plans",
        error:
          "Your current plan does not include UWorld Video Library access. Please upgrade to a plan that includes Video Library.",
      });
    }

    const pointsResult = access.course?.id && user.role === "student"
      ? ngRecordVideoLibraryOpenForStudent(db, {
          user,
          courseId: access.course.id,
          roadmapDayId: req.body.roadmap_day_id || req.body.roadmapDayId || null,
          source: "external_library_sso_open",
          metadata: { route: "/student/external-library/access", access_source: access.source || null },
        })
      : null;

    if (pointsResult && !pointsResult.allowed) {
      return ngBlockLockedFeature(res, "video_library", pointsResult.reason);
    }

    await writeLiveDb(db);

    const token = signExternalLibraryToken({
      user,
      enrollment: access.enrollment,
      plan: access.plan,
      course: access.course,
      accessEndsAt: access.accessEndsAt,
    });

    const redirect_url = `${EXTERNAL_LIBRARY_URL.replace(/\/$/, "")}/sso-login?token=${encodeURIComponent(token)}`;

    res.json({
      success: true,
      redirect_url,
      expires_in_minutes: EXTERNAL_LIBRARY_TOKEN_MINUTES,
      access_ends_at: access.accessEndsAt,
      access_days: access.accessDays,
      plan: access.plan ? sanitizePlan(access.plan) : null,
      course: access.course ? sanitizeCourse(access.course) : null,
      points: pointsResult ? { awarded: pointsResult.awarded, reason: pointsResult.reason, point_event: pointsResult.point_event, leaderboard: pointsResult.leaderboard } : null,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to create external library access link",
    });
  }
});

app.get("/external-library/sso/verify", async (req, res) => {
  try {
    const token = String(req.query.token || "").trim();

    if (!token) {
      return res.status(400).json({
        success: false,
        error: "SSO token is required",
      });
    }

    let decoded;

    try {
      decoded = jwt.verify(token, EXTERNAL_LIBRARY_SSO_SECRET);
    } catch {
      return res.status(401).json({
        success: false,
        error: "SSO token is invalid or expired",
      });
    }

    if (decoded.purpose !== "external_library_sso") {
      return res.status(401).json({
        success: false,
        error: "Invalid SSO token purpose",
      });
    }

    const db = await readLiveDb();
    const user = db.users?.[String(decoded.sub)] || findUserByEmail(db, decoded.email);

    if (!user?.id) {
      return res.status(404).json({
        success: false,
        error: "Student account not found",
      });
    }

    const access = getExternalLibraryAccess(db, sanitizeUser(user));

    if (!access.allowed) {
      return res.status(403).json({
        success: false,
        error: "Video Library access is no longer active for this student",
      });
    }

    res.json({
      success: true,
      student: {
        id: user.id,
        name: user.name || decoded.name || user.email || "NextGen Student",
        email: user.email,
        tier: decoded.tier || "premium",
        accessEndsAt: decoded.accessEndsAt || access.accessEndsAt,
        plan_id: decoded.plan_id || access.plan?.id || null,
        plan_name: decoded.plan_name || access.plan?.name || null,
        course_id: decoded.course_id || access.course?.id || null,
        course_name: decoded.course_name || access.course?.name || null,
      },
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to verify external library SSO token",
    });
  }
});

